/*
*objetivo= sacar multiplos de 3 entre 20 y 40  
*/

package bucles;

public class bucleforEjercicioclase {

	public static void main(String[] args) {
		// TODO Auto-generated method stub


		for ( int i = 20; i<= 40; i++) {
			if (i%3 ==0) {
				System.out.print(i + " ");
			}
			
		}
		
		
		
		
	}

}
